function main(): void {
  const f = new Error("m");
  delete (f as any).stack;
  console.log(f.stack, typeof f.stack);
  try { throw new Error("z"); } catch (e: any) {
    e.stack = "s";
    console.log(e.stack);
    delete e.stack;
    console.log(e.stack, typeof e.stack);
  }
  const g = new TypeError("t");
  console.log(typeof g.stack);
}
